insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-201","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate constant $k$ of a given reaction, at fixed temperature, does not depend on","options":["the concentrations of the reactants","the presence of a catalyst (which actually changes $k$)","temperature (which actually changes $k$)","the activation energy (which actually enters $k$)"],"answer_index":0,"explanation":"$k$ is independent of concentration. It does depend on $T$, $E_a$ and catalysis; the wording isolates the concentration independence.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-202","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Dimensions of $k$ for a zero-order reaction (rate in mol L$^{-1}$ s$^{-1}$) are","options":["mol L$^{-1}$ s$^{-1}$","s$^{-1}$","L mol$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k$ when the order is zero, so $k$ carries the same units as the rate itself.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-203","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A second-order rate constant (concentration in mol L$^{-1}$, time in s) has the unit","options":["L mol$^{-1}$ s$^{-1}$","s$^{-1}$","mol L$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k[\\mathrm{A}]^2$ (or $k[\\mathrm{A}][\\mathrm{B}]$) forces $k$ to have units (concentration)$^{-1}$ (time)$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-204","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Average rate over a finite interval is computed as","options":["change in concentration divided by the elapsed time","the slope of the tangent at one instant only","the equilibrium constant divided by time","the activation energy divided by $RT$"],"answer_index":0,"explanation":"Average rate $= \\Delta[\\mathrm{ ]}/\\Delta t$. Instantaneous rate is the derivative (tangent slope).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-205","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $2\\mathrm{N_2O_5} \\to 4\\mathrm{NO_2} + \\mathrm{O_2}$, the rate of appearance of NO$_2$ compared with the rate of disappearance of N$_2$O$_5$ is","options":["twice as large","the same","half as large","four times smaller"],"answer_index":0,"explanation":"Rate of reaction $= -\\tfrac12 \\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = +\\tfrac14 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$, so $-\\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = \\tfrac12 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-206","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For an elementary bimolecular collision A + B → products, the rate law is expected to be","options":["rate $= k[\\mathrm{A}][\\mathrm{B}]$","rate $= k$ only","rate $= k[\\mathrm{A}]^2[\\mathrm{B}]^2$","rate $= k / [\\mathrm{A}][\\mathrm{B}]$"],"answer_index":0,"explanation":"In an elementary step the molecularity and the order coincide, so each reactant appears to the first power.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-207","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a multi-step mechanism has one distinctly slow step, the observed rate law is usually that of the","options":["rate-determining (slow) step, after any pre-equilibria are substituted","fastest step alone, ignoring the slow one","overall stoichiometry in every case","reverse reaction only"],"answer_index":0,"explanation":"The bottleneck step limits the flux. Intermediates in that step are rewritten using faster equilibria if needed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-208","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Raising the temperature of a typical thermally activated reaction increases $k$ because","options":["a larger fraction of collisions then exceeds the activation barrier","concentrations in the rate law are redefined","the stoichiometric coefficients change","the Faraday constant grows with $T$"],"answer_index":0,"explanation":"Arrhenius behaviour: $k = A e^{-E_a/RT}$ grows rapidly as $T$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-209","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate of the reaction $a\\mathrm{A} \\to$ products is defined so that","options":["rate $= -\\tfrac1a \\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= -a\\,\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= +a[\\mathrm{A}]$","rate $= [\\mathrm{A}]^a$ with no $k$"],"answer_index":0,"explanation":"Dividing by the stoichiometric coefficient makes the rate the same whichever species is monitored.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-210","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If rate $= k[\\mathrm{A}]^2$ and [A] is doubled at constant $T$, the instantaneous rate becomes","options":["four times the original rate","twice the original rate","unchanged","half the original rate"],"answer_index":0,"explanation":"Second order in A: $(2)^2 = 4$, so the rate quadruples.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
